css='''@font-face{font-family:Poppins;src:url(assets/poppins-400.woff2);font-weight:400}@font-face{font-family:Poppins;src:url(assets/poppins-600.woff2);font-weight:600}*{box-sizing:border-box}body{font:14px/1.65 Poppins,sans-serif;color:#13262c;margin:0;background:#fff}header,main,footer{max-width:1220px;margin:auto;padding:28px 30px}header{padding-top:44px;border-bottom:1px solid #dfe7e9}h1{font-size:32px;line-height:1.3;font-weight:600;margin:8px 0 16px}h2{font-size:22px;margin:35px 0 8px}h3{font-size:16px;margin:0 0 8px}p{margin:8px 0;color:#5a6d72;max-width:84ch}a{color:#0f4552;text-underline-offset:4px}a:focus-visible,summary:focus-visible{outline:3px solid #0f4552;outline-offset:4px}.kicker{font-size:12px;color:#5a6d72}.links{display:flex;gap:20px;flex-wrap:wrap;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:36px 28px;margin:24px 0}.tile{min-width:0;border-top:1px solid #dfe7e9;padding-top:16px}.tile img{display:block;width:100%;border:1px solid #dfe7e9;margin:16px 0 8px;background:#f3f6f6}.tile p{font-size:13px}.tile .links{font-size:12px;gap:16px;margin:12px 0}.tag{font-size:11px;color:#5a6d72;margin-bottom:8px}.notice{border-left:3px solid #94570a;padding:8px 18px;margin:25px 0}.ref{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.ref img{width:100%;border:1px solid #dfe7e9}.ref a{font-size:12px}.ref h3{font-size:14px}details{border-top:1px solid #dfe7e9;padding:20px 0}summary{cursor:pointer;font-weight:600;padding:5px 0}footer{border-top:1px solid #dfe7e9;color:#5a6d72;font-size:12px}@media(max-width:759px){header,main,footer{padding:24px 18px}h1{font-size:25px}.grid,.ref{grid-template-columns:1fr}.links{gap:12px 20px}.tile{padding-top:20px}}'''
html=['<!doctype html><html lang="de-AT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Senklot · Premium Feinschliff · Entwürfe</title><style>'+css+'</style></head><body>']
html+=['<header><p class="kicker">SENKLOT · LOT · 28. OKTOBER 2026</p><h1>Vertraut. Klarer im entscheidenden Moment.</h1><p>16 Zustände für einen gezielten UI/UX-Feinschliff. Die bestehende Lot-Linie bleibt Grundlage. Alle neuen Screens sind eigenständige Entwürfe mit fiktiven Daten.</p><div class="notice"><strong>Zur Durchsicht – die App ist unverändert.</strong><p>Keine Änderungen an Produktcode, Daten, Berechtigungen oder Live-App. Die Vorschau simuliert die gezeigten Zustände.</p></div><nav class="links" aria-label="Entwurfspaket"><a href="#entwuerfe">Screens ansehen</a><a href="AUDIT.md">Audit mit Prioritäten</a><a href="FUNKTIONSERHALT.md">Funktionsumfang</a><a href="#bestand">Aktueller Bestand</a><a href="#hinweise">Hinweise</a></nav></header><main>']
html+=['<section id="entwuerfe"><h2>Die vorgeschlagenen Zustände</h2><p>Jeweils Smartphone, Tablet und Desktop. „Vorschau öffnen“ zeigt das eigenständige Designmodell; nur dessen Beispielinteraktionen sind simuliert.</p><div class="grid">']
for key,title,finding,desc in states:
 html+=[f'<article class="tile" id="{key}"><p class="tag">{escape(finding)}</p><h3>{escape(title)}</h3><p>{escape(desc)}</p><a href="screens/{key}-1440.jpg"><img loading="lazy" src="screens/{key}-1440.jpg" alt="Desktopentwurf: {escape(title)}"></a><div class="links"><a href="screens/{key}-390.jpg">Mobil · 390</a><a href="screens/{key}-834.jpg">Tablet · 834</a><a href="screens/{key}-1440.jpg">Desktop · 1440</a><a href="vorschau.html?screen={key}">Vorschau öffnen</a></div></article>']
html+=['</div></section><section><h2>Dunkle Darstellung</h2><p>Prüfung derselben Zustände mit den vorhandenen dunklen Lot-Farben.</p><div class="ref">']
for key in ['rechnung-pdf','verlassen','katalog','buchung-abgelehnt']:
 title=next(s[1] for s in states if s[0]==key)
 html+=[f'<article><h3>{title}</h3><a href="screens/{key}-1440-dunkel.jpg"><img loading="lazy" src="screens/{key}-1440-dunkel.jpg" alt="Dunkler Desktopentwurf: {title}"></a><div class="links"><a href="screens/{key}-390-dunkel.jpg">Mobil dunkel</a><a href="vorschau.html?screen={key}&theme=dark">Vorschau</a></div></article>']
html+=['</div></section><section id="bestand"><h2>Bestehende Ansichten als Referenz</h2><p>Diese Bilder stammen aus der unveränderten React-Vorschau des aktuellen Produktionscommits. Die Daten sind fiktiv. Bereits gute Bereiche werden beibehalten.</p>']
refs=json.loads((root/'bestand-pruefung.json').read_text())
extra=root/'weitere-referenzen.json'
if extra.exists():refs+=json.loads(extra.read_text())
names=list(dict.fromkeys(r['name'] for r in refs))
html+=['<details><summary>Referenzen der Listen, Akten, Formulare, Einstellungen und Plattform öffnen</summary><div class="ref">']
for name in names:
 html+=[f'<article><h3>{escape(name.replace("-"," ").capitalize())}</h3><a href="bestand/{name}-1440.jpg"><img loading="lazy" src="bestand/{name}-1440.jpg" alt="Unveränderte Referenz {escape(name)}"></a><div class="links"><a href="bestand/{name}-390.jpg">Mobil</a><a href="bestand/{name}-834.jpg">Tablet</a><a href="bestand/{name}-1440.jpg">Desktop</a></div></article>']
html+=['</div></details></section><section id="hinweise"><h2>Was die Screens aussagen</h2><p>Sie zeigen den vorgesehenen Umgang mit Zuständen und die gemeinsame Gestaltung. Einzelne Formulare sind Ausschnitte; die übrigen Felder, Tabs und Fachaktionen bleiben in der echten App erhalten. Details stehen im Dokument zum Funktionsumfang.</p><p>Der Button „Status prüfen“ bei unklarer Rechnung ist ein Ablaufentwurf. Die verlässliche technische Zuordnung muss vor einer Umsetzung separat geklärt werden. Ein bloßes Neuladen beweist nicht in jedem Fall, was mit einer bestimmten Anfrage geschehen ist.</p><p>Automatische Layout- und axe-Prüfungen sowie gezielte Bestandsproben wurden durchgeführt. Es gab keinen neuen produktiven Schreibtest und keine vollständige Release-Abnahme. Alle identifizierten App-Befunde sind noch offen.</p><div class="links"><a href="AUDIT.md">Vollständiges Audit</a><a href="FUNKTIONSERHALT.md">Funktionsumfang</a><a href="entwurf-pruefung.json">Messung der Entwürfe</a><a href="bestand-pruefung.json">Messung des Bestands</a><a href="weitere-referenzen.json">Weitere Tabs</a></div></section></main><footer>Senklot · Designentwurf, kein Release · Basis 7601e378 · 28. Oktober 2026 · Zeitangaben Europe/Vienna</footer></body></html>']
(root/'index.html').write_text('\n'.join(html))

